// A creature's full stat block as HTML: used by the tracker's stat block panel, and usable on its
// own (a server can render the same markup into a page). No DOM is needed, so it runs anywhere.
//
// The SRD data (src/data/srd-monsters.json, shipped as `@dm-tabletop/initiative-tracker/srd-monsters.json`)
// is generated by scripts/build-creatures.mjs from the System Reference Document 5.1 (CC-BY-4.0).
// Wherever it is shown, show the credit too (`SRD_CREDIT_HTML`, see NOTICE.md).

export interface MonsterEntry {
  name: string;
  /** Paragraphs separated by "\n"; *text* is italic (as printed). */
  text: string;
}

export interface Monster {
  id: string;
  name: string;
  size: string;
  type: string;
  alignment: string;
  /** As printed, e.g. "17 (natural armor)". */
  armorClass: string;
  ac: number;
  hp: number;
  hitDice: string;
  speed: string;
  str: number;
  dex: number;
  con: number;
  int: number;
  wis: number;
  cha: number;
  saves?: string;
  skills?: string;
  damageVulnerabilities?: string;
  damageResistances?: string;
  damageImmunities?: string;
  conditionImmunities?: string;
  senses?: string;
  languages?: string;
  /** As printed: "1/4", "10". */
  challenge: string;
  cr: number;
  xp: number;
  traits: MonsterEntry[];
  actions?: MonsterEntry[];
  reactions?: MonsterEntry[];
  legendary?: { intro: string; actions: MonsterEntry[] };
  /** Description printed after some stat blocks, one string per paragraph. */
  description?: string[];
}

export interface StatBlockOptions {
  /** Level of the creature's name heading (2 by default); section headings are one below. */
  headingLevel?: number;
  /** id for the name heading, so a panel or page can point aria-labelledby at it. */
  headingId?: string;
  /** Include the description paragraphs after the stat block (off by default). */
  description?: boolean;
}

const LICENCE_URL = 'https://creativecommons.org/licenses/by/4.0/legalcode';
const SRD_URL = 'https://dnd.wizards.com/resources/systems-reference-document';

/** The attribution the CC-BY-4.0 licence asks for, as one short line of HTML. */
export const SRD_CREDIT_HTML =
  `From the <a href="${SRD_URL}">System Reference Document 5.1</a> by Wizards of the Coast LLC, ` +
  `licensed under <a href="${LICENCE_URL}">CC-BY-4.0</a>.`;

export function escapeHtml(text: string): string {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/** Escapes the text, then turns *italic* into <em>. */
function inline(text: string): string {
  return escapeHtml(text).replace(/\*([^*]+)\*/g, '<em>$1</em>');
}

export function abilityModifier(score: number): string {
  const mod = Math.floor((score - 10) / 2);
  return mod >= 0 ? `+${mod}` : `−${-mod}`;
}

/** "1/4 (50 XP)", with the thousands separated as printed. */
export function challengeText(m: Monster): string {
  return `${m.challenge} (${m.xp.toLocaleString('en-US')} XP)`;
}

/** "Small humanoid (goblinoid), neutral evil" */
export function metaText(m: Monster): string {
  return `${m.size} ${m.type}, ${m.alignment}`;
}

function entries(list: MonsterEntry[]): string {
  return list
    .map((e) => {
      const [first, ...rest] = e.text.split('\n');
      const more = rest.map((p) => `<p class="sb-more">${inline(p)}</p>`).join('');
      return `<p><strong><em>${escapeHtml(e.name)}.</em></strong> ${inline(first)}</p>${more}`;
    })
    .join('');
}

const ABILITIES: Array<[keyof Monster, string]> = [
  ['str', 'STR'],
  ['dex', 'DEX'],
  ['con', 'CON'],
  ['int', 'INT'],
  ['wis', 'WIS'],
  ['cha', 'CHA'],
];

const PROPS: Array<[keyof Monster, string]> = [
  ['saves', 'Saving Throws'],
  ['skills', 'Skills'],
  ['damageVulnerabilities', 'Damage Vulnerabilities'],
  ['damageResistances', 'Damage Resistances'],
  ['damageImmunities', 'Damage Immunities'],
  ['conditionImmunities', 'Condition Immunities'],
  ['senses', 'Senses'],
  ['languages', 'Languages'],
];

const prop = (label: string, value: string) =>
  `<div><dt>${escapeHtml(label)}</dt> <dd>${escapeHtml(value)}</dd></div>`;

export function renderStatBlock(m: Monster, options: StatBlockOptions = {}): string {
  const level = Math.min(5, Math.max(1, options.headingLevel || 2));
  const h = `h${level}`;
  const sub = `h${level + 1}`;
  const id = options.headingId ? ` id="${escapeHtml(options.headingId)}"` : '';
  const abilities = ABILITIES.map(
    ([key, label]) =>
      `<div><dt>${label}</dt><dd>${m[key]} (${abilityModifier(m[key] as number)})</dd></div>`,
  ).join('');
  const props = PROPS.filter(([key]) => m[key])
    .map(([key, label]) => prop(label, String(m[key])))
    .join('');
  const section = (title: string, body: string) =>
    `<${sub} class="sb-section">${title}</${sub}>${body}`;
  let html =
    `<div class="sb">` +
    `<${h} class="sb-name"${id}>${escapeHtml(m.name)}</${h}>` +
    `<p class="sb-meta"><em>${escapeHtml(metaText(m))}</em></p>` +
    `<dl class="sb-props">` +
    prop('Armor Class', m.armorClass) +
    prop('Hit Points', `${m.hp} (${m.hitDice.replace(/([+-])/g, ' $1 ')})`) +
    prop('Speed', m.speed) +
    `</dl>` +
    `<dl class="sb-abilities">${abilities}</dl>` +
    `<dl class="sb-props">${props}${prop('Challenge', challengeText(m))}</dl>`;
  if (m.traits.length) html += `<div class="sb-traits">${entries(m.traits)}</div>`;
  if (m.actions && m.actions.length) html += section('Actions', entries(m.actions));
  if (m.reactions && m.reactions.length) html += section('Reactions', entries(m.reactions));
  if (m.legendary) {
    const intro = m.legendary.intro ? `<p>${inline(m.legendary.intro)}</p>` : '';
    html += section('Legendary Actions', intro + entries(m.legendary.actions));
  }
  if (options.description && m.description && m.description.length) {
    html += `<div class="sb-description">${m.description.map((p) => `<p>${inline(p)}</p>`).join('')}</div>`;
  }
  return html + `</div>`;
}

/**
 * The stat block's own styles. Colours come from the surrounding text, plus two variables a host
 * can set: `--sb-accent` (the name and section headings) and `--sb-rule` (the lines between the
 * parts). Nothing else is styled outside `.sb`.
 */
export const statBlockCss = `
.sb { --_sb-accent: var(--sb-accent, currentColor); --_sb-rule: var(--sb-rule, currentColor); line-height: 1.45; }
.sb > * { margin: 0; }
.sb .sb-name { color: var(--_sb-accent); font-size: 1.5em; line-height: 1.2; margin: 0; }
.sb .sb-meta { margin: 2px 0 0; opacity: 0.85; }
.sb dl { margin: 0; }
.sb dt { display: inline; font-weight: 700; }
.sb dd { display: inline; margin: 0; }
.sb .sb-props, .sb .sb-abilities { border-top: 2px solid var(--_sb-rule); padding: 8px 0; }
.sb .sb-props > div { margin: 1px 0; }
.sb .sb-abilities { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 4px; text-align: center; }
.sb .sb-abilities dt, .sb .sb-abilities dd { display: block; }
.sb .sb-abilities dd { font-variant-numeric: tabular-nums; white-space: nowrap; }
.sb .sb-traits { border-top: 2px solid var(--_sb-rule); padding-top: 4px; }
.sb .sb-traits p, .sb .sb-section ~ p { margin: 8px 0 0; }
.sb .sb-more { padding-left: 1em; }
.sb .sb-traits .sb-more, .sb .sb-section ~ .sb-more { margin-top: 2px; }
.sb .sb-section {
  color: var(--_sb-accent); font-size: 1.2em; line-height: 1.3; margin: 16px 0 0; padding-bottom: 2px;
  border-bottom: 1px solid var(--_sb-rule);
}
.sb .sb-description { margin-top: 16px; }
.sb .sb-description p { margin: 8px 0 0; }
@media (max-width: 420px) {
  .sb .sb-abilities { grid-template-columns: repeat(3, minmax(0, 1fr)); row-gap: 8px; }
}
`;
